INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0001', 'Sharing of josh magazine on digital platforms', 'SANTOSH KUMAR', 'E0414', 'M Zink', 'Magazine is available in hardcopy', 'Make magazine in digital form and make printed copy limited to be available for visitors and readers in waiting area', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0002', 'Resale of damaged and rusted container.', 'RAVINDER THAKUR', 'E0414', 'Production', 'The damaged and rusted container thrown as scrap.', 'Resale of damaged and rusted container to the manufacturer.', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0003', 'Safe and efficient drum unloading', 'R&D Team', 'E0414', 'R&D', 'Earlier two person required to take out material from drum which was time consuming, man Power consuming way.', 'Now drums are placed horizontally at an angle so that material can be take out easily without any etra power. There is a open close value attached with the drum that helps in taking out the sample without any spillage.', 'Productivity', 7, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0004', 'Segregation of all packing bottles/can and lida', 'R&D Team', 'E0414', 'R&D', 'Earlier we are facing issue in finding the correct size can /bottles. Finding caps/lids of these bottles was a time consuming process due to fwo manufacturer CNC and ACP.', 'Seperate Cage was made for segregation so that everything can be find and selected easily.', 'Productivity', 2, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0005', 'Cover for waste Sink', 'R&D Team', 'E0414', 'R&D', 'In our lab earlier there were open sinks in which we wash out lab apparatus with solvents. The open sink system was not efficient in minimizing the solvent evaporation. The evaporated solvent was contributing in bad lab smell and VOC', 'We designed a lid on the top of the sink that can be taken off when used and can be put on when not in used', 'Quality', 3, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0006', 'POLICY FORMATION FOR LEARNING THROUGH ONLINE PORTALS LIKE SWAYAM', 'SANTOSH KUMAR', 'E0414', 'M Zink', 'DO NOT HAVE ANY POLICY FOR ONLINE LEARNING PLATFORMS', 'TO ENCOURAGE OUR EMPLOYEES FOR SKILL DEVELOPMENT THROUGH ONLINE PORTALS LIKE SWAYAM .ON SUCCESFUL COMPLETION OF COURSE SBL CAN REIMBURSE THE COST WHICH VERY LESS (APPROX-500 RUPEES )', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0007', 'Testing management system', 'SHUBHAM', 'E0414', 'R&D', 'As of now we don''t have any system to track and manage long term testing. Most of the time user miss test due date , observation date due to multiple number of testing. Additionally we don''t have any system that can record and save the testing details of any panel or any chemistry. This will help us in observing the data in future.', 'A online system that records the data of panel , testing, provide transperancy to the tester and save records for future use.', 'Quality', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0008', 'implementation of charging hopper along with stool to get ease of operation and less spillage at floor', 'BHISHMA VERMA', 'E0414', 'Production', 'there is direct facility for powder bag charging into HSD which result in power spillage, chances of bag goes into HSD', 'Charging hopper with stool provided and currently charging operation got smooth', 'Productivity', 6, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0009', 'Cleaning system for mixers(Opaque/Primer, Metallic and Clear)by implementing AODD pump facility with piping system', 'BHISHMA VERMA', 'E0414', 'Production', 'Before installation of new cleaning facility , we were doing the big size mixers manually with long brush, now cleaning system has been implemented with some mixers and rest mixers same implementation is going on', 'Cleaning system for mixers(Opaque/Primer, Metallic and Clear)by implementing AODD pump facility with piping system', 'Quality', 6, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0010', 'Improving efficiency of STP Pump', 'Arun Kumar', 'E0414', 'Maintenance', 'Currently STP pump gets pebbles and stones in line which damage the water meter, to prevent damage to water meter, the line was equipped with SS Jali, which gets choked easily due to dirt so flow of pump gets reduced.', 'Pump should be lifted 6 inches from floor level so that debris and dirt does not get into the pump and flow of water is increased.', 'Cost', 6, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000011', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2025-0011', 'Clamp for pipe Jerk handle', 'Manish Kumar', 'E0414', 'Production', 'डिस्पेंसिंग प्वाइंट प्वाइंट पर मटेरियल ट्राली में डालते समय , प्रेशर से पाइप का बाहर आ जाना, जिससे मटेरियल स्पिलेज का खतरा रहता है, और आदमी के चोट लगने की संभावना होना।', 'क्लैम्प की सहायता से इसको पकड़ के रख सकते है जिससे पाइप पे, प्रेशर के कारण झटका लगने पर रोका जा सकता है या कम किया जा सकता है।', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000012', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0012', 'container reuse after rmqc testing', 'Akash kumar', 'E0414', 'Production', 'new containers after testing in rmqc throw out for scraping', 'to use these containers for batch making as same required in R&D and  foc samples', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000013', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0013', 'Elimination of 20LTR Barrel cutting by using Borescope Camera for Internal Checking.', 'Mohit Sandhu', 'E0414', 'RMQC', 'For checking inside cleanliness and Glue of 20 ltr barrels, barrels is cut using cutter/blade.
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000014', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0014', 'MAKE A DIGITAL LETTER REGISTER', 'KHUSHI', 'E0414', 'HR', 'CURRENTLY WE ARE NOTING DOWN THE DATA IN THE REGISTERS', 'WE PROPOSE TO CREATE A DIGITAL LETTER REGISTRY SYSTEM', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000015', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0015', 'DRUM PAINTING', 'KHUSHI', 'E0414', 'HR', 'WE HAVE DAMAGE DRUMS ON SITE WHICH CAN BE UTILIZED CREATIVELY', 'COST SAVING', 'Cost', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000016', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0016', 'CREATE A GOOGLE FORM IN WHICH WE PROVIDE LABOUR BENEFIT TO ALL THE EMPLOYEES', 'KHUSHI', 'E0414', 'HR', 'BEFORE THAT WE USE PAPER FORM BUT NOW WE USE GOOGLE FORM', 'PSYCHOSOCIAL IMPROVEMENT', 'Safety', 1, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000017', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0017', 'PORTABLE SPRINKLING SYSTEM', 'KHUSHI', 'E0414', 'HR', 'CURRENTLY WE ARE USING WATER HOS PIPE FOR WATERING IN THE GARDEN', 'PORTABLE SPRINKLER SYSTEM TO BE USED FOR AUTOMATING THE WATER PROCESS', 'Productivity', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000018', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0018', 'Automation of water filling of water tanks', 'Tarun Bansal', 'E0414', 'Engineering', 'Currently manpower is engaged in filling of water tank manually', 'Automation is proposed so that water is filled in automated mode when the tank is empty', 'Productivity', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000019', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0019', 'DRUM PAINTING', 'KHUSHI', 'E0414', 'HR', 'WE HAVE DAMAGE DRUMS ON SITE WHICH CAN BE UTILIZED CREATIVELY', 'USE AS FOR AESTHETICS', 'Safety', 1, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000020', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0020', 'Underground tank manhole cover', 'Chandra Mohan', 'E0414', 'Engineering', 'The rainwater underground storage tank has elevated manhole cover.', 'Elevated manhole cover to be removed as vehicles may get collision', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000021', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0021', 'Kitchen Waste Storage Bin', 'Surjit kumar', 'E0414', 'HR', 'Currently kitchen waste is stored in 200 liters metallic drums, in which food starts to rot due to moisture and closed condition.', 'A trolley with perforated jali to be fabricated for storing of kitechen waste', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000022', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0022', 'Use of magnet to hold termperature meter', 'SHUBHAM', 'E0414', 'R&D', 'Currently temperature meter is kept on working area which hinders work', 'Temperature meter shall be hanged on hollow metal surface using magnet', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000023', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0023', 'Use of wrist band to dissipate static electricity', 'Anonymous', 'E0414', 'General', 'Currently there is no continous provision to dissipate body static earthing', 'Use of netallic wrist band to dissipate static earthing', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000024', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0024', 'Bigger Earthing clamp', 'Anonymous', 'E0414', 'General', 'Currently wrist band have small clamp which dont fit on trolley', 'bigger clamp to be fit so that earthing can be done properly', 'Safety', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000025', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0025', 'FLP Weighing Balance', 'Tarun Bansal', 'E0414', 'Engineering', 'The weighing balance in Unit 1 were not FLP and to procure all new 36 FLP weighing balance a cost of Rs 40 lacs was qouted.', 'It was proposed to change to indictor of the weighing balance only which was qouted Rs 6 lacs only. and make weighing balance', 'Cost', 85, 'Completed', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000026', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0026', 'Kaizen Proposal', 'BHISHMA VERMA', 'E0414', 'General', 'CURRENTLY COVERS ARE IN TWO PARTS AND OUT LET PIPE FROM DYNO MILL ATTACHED TO TROLLEY RESULTING IN LID TO OPEN , RESULTING IN SOLVENT EVAPORATE', 'TROLLEY LID TO BE PROPER COVER WITH TOP HAVING HOLE FOR OUT LET PIPE ATTACHMENT', 'Quality', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000027', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0027', 'Kaizen Proposal', 'Heena', 'E0414', 'General', 'Currently, every laboratory does not have a dedicated first aid box. Minor injuries such as cuts from blades, glassware, or chemical splashes may not receive immediate treatment. There is also no defined person responsible for checking first aid supplies regularly, which may lead to expired or missing items. This can delay treatment, increase safety risks, and affect employee confidence.', 'Install one standard first aid box in every laboratory and on each production floor
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000028', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0028', 'Kaizen Proposal', 'Pankaj kumar', 'E0414', 'General', 'All acids bottles are kept in tray with sand below bottles.', 'We kept all acids bottles in tray with sand.', 'Safety', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000029', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0029', 'Kaizen Proposal', 'Jyoti SHarma', 'E0414', 'General', 'Tipco Electrical Cabinet was mounted at a height not safe for operation.', 'Asked to remount the Electrical Cabinet at a height where user''s height can be reached easily.', 'Safety', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000030', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0030', 'Kaizen Proposal', 'Heena', 'E0414', 'General', 'Currently, various notifications, circulars, instructions and important information are pasted directly on the walls of the R&D department. This creates an unorganized appearance, increases wall clutter and makes it difficult to identify important and updated information', 'Provide a dedicated notice board at a suitable and easily visible location in the R&D department. All official notifications, important instructions, safety information, announcements and other relevant communication should be displayed systematically on the notice board. Old or expired notices should be removed periodically to maintain the board in an updated and organized condition', 'Productivity', 85, 'Assessor Verified', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000031', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0031', 'Kaizen Proposal', 'Utsav Arora', 'E0414', 'General', 'Time taken to pump 5KL batch raw material is too long', 'Change Diaphragm Pump with other reactor pump which is more fast and less noisy.', 'Productivity', 85, 'Submitted', 100) ON CONFLICT DO NOTHING;
INSERT INTO public.kaizen_proposals (id, company_id, facility_id, kaizen_number, title, submitter_name, submitter_employee_code, department, problem_statement, solution_implemented, benefit_type, total_score, status, reward_points) VALUES ('70000000-0000-0000-0000-000000000032', '00000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000002', 'KZN-2026-0032', 'Kaizen Proposal', 'B R Maurya', 'E0414', 'General', 'There are lot of fumes during charging and unloading batches of Resin.', 'Install exhaust fan on the wall behind reactors at ground floor. Also change the place of exhaust fan at boiler area to improve suction of boiler fumes.', 'Safety', 85, 'Submitted', 100) ON CONFLICT DO NOTHING;
